use std::io::{self, Read};

fn solve(n: usize, s: Vec<char>) -> Vec<char> {
    let mut count_sf = 0;
    let mut count_fs = 0;

    for i in 1..n {
        match (s[i - 1], s[i]) {
            ('S', 'F') => count_sf += 1,
            ('F', 'S') => count_fs += 1,
            _ => {}
        }
    }

    if count_sf > count_fs {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}

fn main() {
    // Read the entire input
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    // Parse n and the sequence string
    let mut parts = input.split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let s_str = parts.next().unwrap();

    // Convert the string into a Vec<char>
    let s_vec: Vec<char> = s_str.chars().collect();

    // Call solve and collect the result into a String
    let answer_chars = solve(n, s_vec);
    let answer: String = answer_chars.into_iter().collect();

    // Print the result
    println!("{}", answer);
}